import{_ as a,C as t,o,c as r,j as e,a as i,E as l,a6 as p}from"./chunks/framework.BNHADhRC.js";const v=JSON.parse('{"title":"1.1 MSW 是什么","description":"","frontmatter":{},"headers":[],"relativePath":"01-introduction/index.md","filePath":"01-introduction/index.md","lastUpdated":1792642815000}'),d={name:"01-introduction/index.md"};function c(h,s,u,b,m,g){const n=t("MockBadge");return o(),r("div",null,[s[0]||(s[0]=e("h1",{id:"_1-1-msw-是什么",tabindex:"-1"},[i("1.1 MSW 是什么 "),e("a",{class:"header-anchor",href:"#_1-1-msw-是什么","aria-label":'Permalink to "1.1 MSW 是什么"'},"​")],-1)),l(n),s[1]||(s[1]=p(`<blockquote><p>🌐 本教程的在线站点：<a href="https://yzhijie.github.io/msw-tutorial/" target="_blank" rel="noreferrer">https://yzhijie.github.io/msw-tutorial/</a> ，其中<a href="https://yzhijie.github.io/msw-tutorial/comics/index.html" target="_blank" rel="noreferrer">漫画剧场</a>也一并部署；每次向源码仓库推送 main，站点会由 Actions 自动重新构建发布。</p></blockquote><p><strong>Mock Service Worker（MSW）</strong> 是一个 API 模拟工具：它使用 <strong>Service Worker</strong>（浏览器）或 <strong>请求拦截（Node）</strong> 在<em>应用的网络层</em>截获请求，并用你编写的 handler 返回模拟响应。</p><p>应用代码完全无感知 —— 你写的还是普通的 <code>fetch(&quot;/api/users&quot;)</code>，浏览器 DevTools 的 Network 面板里甚至能看到这条&quot;请求&quot;以及它的状态码、响应头和响应体。</p><h2 id="为什么需要它" tabindex="-1">为什么需要它 <a class="header-anchor" href="#为什么需要它" aria-label="Permalink to &quot;为什么需要它&quot;">​</a></h2><p>在前后端分离的项目里，前端开发常常面临：</p><table tabindex="0"><thead><tr><th>痛点</th><th>传统做法（手写 mock / json-server / 改代码）</th><th>MSW 的做法</th></tr></thead><tbody><tr><td>后端接口没就绪</td><td>业务代码里写死假数据，联调前再删</td><td>真实发请求，网络层返回，业务代码零侵入</td></tr><tr><td>想测 500 / 超时</td><td>手动改代码或后端配合</td><td>一个开关切换错误状态与延迟</td></tr><tr><td>单元测试 mock 与开发 mock 两套</td><td><code>vi.mock</code> 与 mock 文件各写一份</td><td><strong>同一套 handler</strong>，浏览器和 Node 共用</td></tr><tr><td>DevTools 看不到请求</td><td>数据凭空出现，难以排查</td><td>请求真实经过网络栈，Network 面板完整可见</td></tr><tr><td>想模拟 WebSocket</td><td>依赖 mock-socket 等三方库</td><td>MSW 3 内置原生 WebSocket 拦截</td></tr></tbody></table><p>核心理念一句话：<strong>mock 应该发生在网络边界上，而不是散落在应用代码里。</strong></p><h2 id="工作原理-浏览器" tabindex="-1">工作原理（浏览器） <a class="header-anchor" href="#工作原理-浏览器" aria-label="Permalink to &quot;工作原理（浏览器）&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  你的应用                    浏览器网络栈                    真实服务器</span></span>
<span class="line"><span> ┌──────────┐   fetch()    ┌─────────────────────┐</span></span>
<span class="line"><span> │ 业务代码 │ ───────────▶ │ Service Worker 注册  │</span></span>
<span class="line"><span> │ (无感知) │              │  mockServiceWorker  │</span></span>
<span class="line"><span> └──────────┘              └─────────┬───────────┘        ┌──────────┐</span></span>
<span class="line"><span>       ▲                            │ 匹配 handler？       │ 后端 API │</span></span>
<span class="line"><span>       │  Response                  ▼                     └──────────┘</span></span>
<span class="line"><span>       │                    ┌─────────────────┐</span></span>
<span class="line"><span>       └────────────────────│ 你的 handlers    │</span></span>
<span class="line"><span>        状态码/头/JSON/延迟  │ http/ws/graphql │</span></span>
<span class="line"><span>                            └─────────────────┘</span></span>
<span class="line"><span>                                  │ 未匹配</span></span>
<span class="line"><span>                                  ▼</span></span>
<span class="line"><span>                            passthrough() → 放行到真实服务器</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>三个角色（本教程漫画「信标驿站」里的拟人化设定）：</p><ol><li><strong>请求小邮差</strong>：你应用发出的每个 HTTP / WS 请求。</li><li><strong>Worker 站长</strong>：注册在页面同源下的 <code>mockServiceWorker.js</code>，所有出域请求先经过它，按规则决定&quot;自己回信&quot;还是&quot;放行&quot;。</li><li><strong>服务端大熊</strong>：真实后端（或 MSW 在 Node 测试里扮演的拦截层）。</li></ol><h2 id="msw-3-的关键变化-v2-→-v3-迁移要点" tabindex="-1">MSW 3 的关键变化（v2 → v3 迁移要点） <a class="header-anchor" href="#msw-3-的关键变化-v2-→-v3-迁移要点" aria-label="Permalink to &quot;MSW 3 的关键变化（v2 → v3 迁移要点）&quot;">​</a></h2><p>本教程基于 <strong>MSW 3.0.x</strong>，如果你见过 v1/v2 的教程，以下差异必须记住：</p><ol><li><strong>命名空间按协议拆分子路径</strong>： <ul><li><code>http</code>、<code>HttpResponse</code> 仍从 <code>msw</code> 导入；</li><li><code>graphql</code> 改为从 <strong><code>msw/graphql</code></strong> 导入（并需要 peer 依赖 <code>graphql</code>）；</li><li>WebSocket 的 <code>ws</code> 从 <strong><code>msw/ws</code></strong> 导入。</li></ul></li><li><strong>原生 WebSocket</strong>：<code>ws.link(&quot;ws://…&quot;)</code> + 事件驱动 API，不再需要 mock-socket。</li><li><code>onUnhandledRequest</code> 更名为 <strong><code>onUnhandledFrame</code></strong>，统一表示&quot;未处理的 HTTP 请求 / WS 帧&quot;。</li><li>handler 数组类型用 <strong><code>AnyHandler[]</code></strong>（HTTP 与 WS handler 的联合）。</li><li>浏览器客户端事件只有 <code>open</code> / <code>message</code> / <code>close</code>（没有独立 <code>error</code> 事件上的帧语义，错误通过关闭码表达）。</li><li>官方提供 <code>msw/vite</code> 插件（<code>virtual:msw</code>）作为可选的零文件集成方式；本教程使用经典的 <code>public/mockServiceWorker.js</code> 方式，原理更透明。</li></ol><h2 id="本教程怎么学" tabindex="-1">本教程怎么学 <a class="header-anchor" href="#本教程怎么学" aria-label="Permalink to &quot;本教程怎么学&quot;">​</a></h2><ul><li><strong>第二章</strong>：5 分钟把 worker 跑起来；</li><li><strong>第三 ~ 六章</strong>：按&quot;启动 → 拦截 → 响应 → 高级&quot;的顺序系统讲解 API；</li><li><strong>第七章</strong>：综合场景与<strong>交互实验室</strong> —— 本页面右上角的徽章如果显示&quot;拦截中&quot;，说明你此刻就可以直接在文档里发请求。</li></ul><p>想要完整工程？仓库提供两个<strong>功能完全对等</strong>的独立可运行示例：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:react</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # http://localhost:5173  React 19 + TypeScript</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:vue</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # http://localhost:5174  Vue 3.5 + Pinia + TypeScript</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>不想 clone 仓库？也可以在 StackBlitz（WebContainers）中在线打开整个 monorepo 运行： <a href="https://stackblitz.com/github/YZhiJie/msw-tutorial-project" target="_blank" rel="noreferrer">在 StackBlitz 中打开</a>。 （仓库为私有访问时，需先在 StackBlitz 登录 GitHub 并完成授权。）</p>`,19))])}const S=a(d,[["render",c]]);export{v as __pageData,S as default};
